// FindMany retrieves multiple Invoice records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *InvoiceRepository) FindMany(ctx context.Context, filter *InvoiceFilter, opts *InvoiceFindOptions) ([]*types.Invoice, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}

	// Build selected fields in OrderedMembers order so FK columns match scan order.
	fieldStrings := invoiceFieldStrings(opts.Fields)

	// Validate fields
	if err := validateFields(fieldStrings, InvoiceAllowedFields); err != nil {
		return nil, 0, err
	}

	// Build SELECT clause
	selectFields := buildSelectFieldsTyped(fieldStrings, "invoice")
	if selectFields == "" {
		return nil, 0, fmt.Errorf("no valid fields specified")
	}

	// Build WHERE clause
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)

	// Build ORDER BY clause
	orderByClause := buildInvoiceOrderByClause(opts.OrderBy, `invoice`)

	// Build LIMIT/OFFSET clause
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)

	// Build query
	query := fmt.Sprintf(`SELECT %s FROM invoice%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)

	// Get total count, unless the options skip it (D89)
	totalCount := -1
	if !opts.SkipCount {
		countQuery := fmt.Sprintf(`SELECT COUNT(*) FROM invoice%s`, whereClause)

		var countRow pgx.Row
		if r.tx != nil {
			countRow = r.tx.QueryRow(ctx, countQuery, args...)
		} else {
			countRow = r.db.pool.QueryRow(ctx, countQuery, args...)
		}
		if err := countRow.Scan(&totalCount); err != nil {
			return nil, 0, fmt.Errorf("failed to get count: %w", err)
		}
	}

	results, err := r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, 0, err
	}
	return results, totalCount, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for the rows of another
// table's read (D90), which counts nothing, as the TypeScript
// repositories' include does.
func (r *InvoiceRepository) findRelated(ctx context.Context, filter *InvoiceFilter, opts *InvoiceFindOptions) ([]*types.Invoice, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	fieldStrings := invoiceFieldStrings(opts.Fields)
	if err := validateFields(fieldStrings, InvoiceAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "invoice")
	if selectFields == "" {
		return nil, fmt.Errorf("no valid fields specified")
	}
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)
	orderByClause := buildInvoiceOrderByClause(opts.OrderBy, `invoice`)
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)
	query := fmt.Sprintf(`SELECT %s FROM invoice%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)
	return r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
}

// invoiceFieldStrings are the columns fields selects, in OrderedMembers
// order so FK columns match scan order, and the primary key when fields
// hydrates a hasMany relation, which maps the children by it.
func invoiceFieldStrings(fields InvoiceFields) []string {
	var fieldStrings []string
	if fields.Id {
		fieldStrings = append(fieldStrings, "id")
	}
	if fields.Number {
		fieldStrings = append(fieldStrings, "number")
	}
	if fields.Status {
		fieldStrings = append(fieldStrings, "status")
	}
	if fields.StatusEnteredAt {
		fieldStrings = append(fieldStrings, "status_entered_at")
	}
	if fields.Payment {
		fieldStrings = append(fieldStrings, "payment")
	}
	if fields.PaymentEnteredAt {
		fieldStrings = append(fieldStrings, "payment_entered_at")
	}
	if fields.Version {
		fieldStrings = append(fieldStrings, "_version")
	}
	return fieldStrings
}

// findRows runs query, a select of the columns fieldStrings names, in turn,
// with args, scans its rows, and hydrates the relations fields selects, as
// FindMany and FindPage read them. method names the caller in an error.
func (r *InvoiceRepository) findRows(ctx context.Context, method, query string, args []interface{}, fieldStrings []string, fields InvoiceFields) ([]*types.Invoice, error) {
	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Invoice{}
	for rows.Next() {
		result := &types.Invoice{}

		// Create temporary variables for nullable fields that need pointer scanning (per-row)

		var tempStatusEnteredAt *types.TemporalDateTime
		var tempPaymentEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these directly on the struct)

		// Track whether special fields were selected so we can post-process after Scan.

		var selectedStatusEnteredAt bool
		var selectedPaymentEnteredAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "number":
				scanDest[i] = &result.Number
			case "status":
				scanDest[i] = &result.Status
			case "status_entered_at":
				scanDest[i] = &tempStatusEnteredAt
				selectedStatusEnteredAt = true
			case "payment":
				scanDest[i] = &result.Payment
			case "payment_entered_at":
				scanDest[i] = &tempPaymentEnteredAt
				selectedPaymentEnteredAt = true
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, fmt.Errorf("unexpected field %q for Invoice.%s", fieldName, method)
			}
		}

		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present
		var jsonFieldDecodeErr error

		if selectedStatusEnteredAt && tempStatusEnteredAt != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.StatusEnteredAt = tempStatusEnteredAt
		}
		if selectedPaymentEnteredAt && tempPaymentEnteredAt != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.PaymentEnteredAt = tempPaymentEnteredAt
		}
		if jsonFieldDecodeErr != nil {
			return nil, jsonFieldDecodeErr
		}

		// Set relationship IDs from scanned FK values (hydration happens after loop)

		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	// Batch hydrate relationships (outside the row loop for efficiency)

	return results, nil
}

// FindPage reads a page of the Invoice rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *InvoiceRepository) FindPage(ctx context.Context, filter *InvoiceFilter, opts *InvoicePageOptions) (*InvoicePage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Invoice rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = InvoiceSortById
	}
	column, ok := invoiceSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Invoice sorts by id, number, status and payment, not %q", string(field))
	}
	byKey := field == InvoiceSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := invoiceFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, InvoiceAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "invoice")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		if byKey {
			conditions = append(conditions, fmt.Sprintf(`invoice.id %s %s`, comparison, placeholder))
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			conditions = append(conditions, fmt.Sprintf(`(%s, invoice.id) %s ((SELECT %s FROM invoice AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder))
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if !byKey {
		orderByClause += fmt.Sprintf(`, invoice.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM invoice%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &InvoicePage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = invoicePageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *InvoiceRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM invoice WHERE invoice.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Invoice row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Invoice row through the behaviors' core (D103), in
// a transaction: each behavior's create initializes the fields it owns, and
// the row is read back. A refusal of the core's is returned as the
// *rules.Refusal it is.
func (r *InvoiceRepository) CreateOne(ctx context.Context, input *InvoiceCreate) (*types.Invoice, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Invoice, error) {
		return (&InvoiceRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// invoiceUniqueKeys are the conflict targets of Invoice's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert only if changed reads back, empty for a
// key over an expression, and the key's columns as a batch insert's cells
// name them (D89).
var invoiceUniqueKeys = map[InvoiceUniqueKey]struct {
	conflict, keep, rows string
	columns              []string
}{
	InvoiceUniqueById: {`(id)`, `id = invoice.id`, `SELECT "id", "number", "status", "status_entered_at", "payment", "payment_entered_at", "_version" FROM invoice WHERE (id) IN (%s)`, []string{`id`}},
}

// invoiceKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func invoiceKeyOf(on InvoiceUniqueKey, row *types.Invoice) (string, bool) {
	switch on {
	case InvoiceUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *InvoiceRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Invoice, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *InvoiceRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Invoice, error) {
	result := &types.Invoice{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempStatusEnteredAt *types.TemporalDateTime
	var tempPaymentEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&result.Number,

		&result.Status,

		&tempStatusEnteredAt,

		&result.Payment,

		&tempPaymentEnteredAt,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempStatusEnteredAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.StatusEnteredAt = tempStatusEnteredAt
	}
	if tempPaymentEnteredAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentEnteredAt = tempPaymentEnteredAt
	}

	// Set relationship IDs from scanned FK values

	return result, nil
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
// statement of an encrypted field.
func (r *InvoiceRepository) upsertRow(ctx context.Context, input *types.Invoice, on InvoiceUniqueKey, update *InvoiceUpdate, onlyIfChanged bool) (*UpsertResult[*types.Invoice], error) {
	key := invoiceUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := invoiceUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: number
	fields = append(fields, `number`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Number)
	// Required field: status
	fields = append(fields, `status`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Status)
	// Optional field: statusEnteredAt - only add if set
	{
		if input.StatusEnteredAt != nil {
			fields = append(fields, `status_entered_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.StatusEnteredAt))
		}
	}
	// Required field: payment
	fields = append(fields, `payment`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Payment)
	// Optional field: paymentEnteredAt - only add if set
	{
		if input.PaymentEnteredAt != nil {
			fields = append(fields, `payment_entered_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.PaymentEnteredAt))
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Number != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`number = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `invoice.number`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Number)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field leaves the row as it is, stamps and
		// all, and returns it.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO invoice (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "number", "status", "status_entered_at", "payment", "payment_entered_at", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Invoice]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Invoice]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with already held the update's values.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Invoice row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Invoice{input})
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Invoice]{Row: found[0], Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// only if changed, and the second statement of each encrypted field.
func (r *InvoiceRepository) upsertBatches(ctx context.Context, inputs []*types.Invoice, on InvoiceUniqueKey, update InvoiceFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Invoice], error) {
	key := invoiceUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Number {
		setClauses = append(setClauses, `number = EXCLUDED.number`)
		compareCurrent = append(compareCurrent, `invoice.number`)
		compareNext = append(compareNext, `EXCLUDED.number`)
	}

	results := make([]UpsertResult[*types.Invoice], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := invoiceUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: number
			{
				cell := batchInsertCell{column: `number`, set: true}
				cell.value = input.Number
				row = append(row, cell)
			}
			// Required field: status
			{
				cell := batchInsertCell{column: `status`, set: true}
				cell.value = input.Status
				row = append(row, cell)
			}
			// Optional field: statusEnteredAt
			{
				cell := batchInsertCell{column: `status_entered_at`}
				if input.StatusEnteredAt != nil {
					cell.value = time.Time(*input.StatusEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: payment
			{
				cell := batchInsertCell{column: `payment`, set: true}
				cell.value = input.Payment
				row = append(row, cell)
			}
			// Optional field: paymentEnteredAt
			{
				cell := batchInsertCell{column: `payment_entered_at`}
				if input.PaymentEnteredAt != nil {
					cell.value = time.Time(*input.PaymentEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field leaves each row as it is.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO invoice (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "number", "status", "status_entered_at", "payment", "payment_entered_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = invoiceKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Invoice], len(prepared))
		for n, row := range returned {
			text, ok := invoiceKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Invoice wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Invoice]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, only if changed,
		// which it reads back by its key, or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged {
				return nil, fmt.Errorf("the Invoice row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Invoice, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Invoice row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Invoice]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *InvoiceRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Invoice, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Invoice
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *InvoiceRepository) rowsOfKeys(ctx context.Context, on InvoiceUniqueKey, keys [][]any, inputs []*types.Invoice) ([]*types.Invoice, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(invoiceUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Invoice{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := invoiceKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Invoice, len(inputs))
	for i, input := range inputs {
		text, _ := invoiceKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Invoice row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// CreateMany inserts multiple Invoice rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *InvoiceRepository) CreateMany(ctx context.Context, inputs []*InvoiceCreate) ([]*types.Invoice, error) {
	if len(inputs) == 0 {
		return []*types.Invoice{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Invoice, error) {
		repo := &InvoiceRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Invoice, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Invoice row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *InvoiceRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *InvoiceUpdate) (*types.Invoice, error) {
	if update == nil {
		update = &InvoiceUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Invoice, error) {
		repo := &InvoiceRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Invoice", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return nil, behaviorNotFound(err, "Invoice", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Invoice records matching the filter
func (r *InvoiceRepository) UpdateMany(ctx context.Context, filter *InvoiceFilter, update *InvoiceUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Number != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`number = $%d`, paramNum))
		values = append(values, *update.Number)
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE invoice SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Invoice row by ID through the
// behaviors' core (D103), in a transaction. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *InvoiceRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Invoice", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Invoice", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Invoice records matching the filter
func (r *InvoiceRepository) DeleteMany(ctx context.Context, filter *InvoiceFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM invoice%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
